#!/usr/bin/env python3
import csv
from collections import deque

graph = {}
with open('/home/user/cleaned_edges.csv', 'r') as f:
    reader = csv.reader(f)
    for row in reader:
        if len(row) < 2:
            continue
        src = row[0].strip()
        dst = row[1].strip()
        graph.setdefault(src, []).append(dst)

start = 'NODE_001'
target = 'NODE_999'

if start == target:
    distance = 0
else:
    queue = deque([(start, 0)])
    visited = {start}
    distance = -1
    while queue:
        node, d = queue.popleft()
        found = False
        for neighbor in graph.get(node, []):
            if neighbor == target:
                distance = d + 1
                found = True
                break
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, d + 1))
        if found:
            break

with open('/home/user/result.txt', 'w') as f:
    f.write(str(distance) + '\n')

print(distance)
